const fs = require("fs");
const path = require("path");
const { register } = require("module");
const { pathToFileURL } = require("url");

const dist = "/w/node_modules/@vitest/browser/dist";
const entry = path.join(dist, "expect-element.js");

// Collect the names each file imports from vitest modules, so the stubs export exactly those.
const names = {};
function collect(file) {
  const src = fs.readFileSync(file, "utf8");
  for (const m of src.matchAll(/import\{([^}]*)\}from"(vitest(?:\/[a-z/]+)?)"/g)) {
    names[m[2]] ??= new Set();
    for (const part of m[1].split(",")) names[m[2]].add(part.trim().split(/\s+/)[0]);
  }
  for (const m of src.matchAll(/import"(vitest(?:\/[a-z/]+)?)"/g)) names[m[1]] ??= new Set();
  return src;
}
const entrySrc = collect(entry);
for (const m of entrySrc.matchAll(/from"\.\/([^"]+)"/g)) collect(path.join(dist, m[1]));

// A stand-in that accepts any property access, call, or construction.
function absorb() {
  const cache = new Map();
  const p = new Proxy(function () {}, {
    get(t, k) {
      if (k === "then") return undefined;
      if (k === Symbol.toPrimitive) return () => "";
      if (k === Symbol.iterator) return function* () {};
      if (typeof k === "symbol") return t[k];
      if (!cache.has(k)) cache.set(k, absorb());
      return cache.get(k);
    },
    apply: () => absorb(),
    construct: () => absorb(),
    set: () => true,
  });
  return p;
}
globalThis.__ludionMatchers = {};
