  if (mod === "vitest" && name === "expect") {
    return { extend(m) { Object.assign(globalThis.__ludionMatchers, m); } };
  }
  if (mod === "vitest/browser" && name === "server") {
    return { config: { browser: { name: "chromium", locators: { exact: false, testIdAttribute: "data-testid" }, providerOptions: {} } } };
  }
  return absorb();
};
globalThis.window = globalThis;
globalThis.__vitest_browser_runner__ = absorb();

const stubs = {};
for (const [mod, set] of Object.entries(names)) {
  const body = [...set].map((n) => "export const " + n + " = globalThis.__ludionStub(" + JSON.stringify(mod) + ", " + JSON.stringify(n) + ");").join("\n");
  stubs[mod] = "data:text/javascript," + encodeURIComponent(body + "\nexport {};");
}
const hooks = "const STUBS = " + JSON.stringify(stubs) + ";\n" +
  "export async function resolve(specifier, context, next) {\n" +
  "  if (Object.hasOwn(STUBS, specifier)) return { url: STUBS[specifier], shortCircuit: true };\n" +
  "  return next(specifier, context);\n" +
  "}\n";
register("data:text/javascript," + encodeURIComponent(hooks));

class FakeNode {}
const view = { Node: FakeNode, HTMLElement: FakeNode, SVGElement: FakeNode };
