  e.ownerDocument = { defaultView: view };
  return e;
}

(async () => {
  await import(pathToFileURL(entry).href);
  const m = globalThis.__ludionMatchers;
  if (typeof m.toHaveTextContent !== "function") {
    console.error("ERROR: expect-element.js did not register toHaveTextContent");
    process.exit(2);
  }
  const ctx = { isNot: false, utils: absorb(), equals: () => false, customTesters: [] };
  const exact = m.toHaveTextContent.call(ctx, element("Error!"), "Error!");
  const partial = m.toHaveTextContent.call(ctx, element("Error!"), "Error");
  console.log("toHaveTextContent('Error!') on 'Error!': pass=" + exact.pass);
  console.log("toHaveTextContent('Error') on 'Error!': pass=" + partial.pass);
  if (exact.pass !== true) {
    console.error("ERROR: an exact text did not match");
    process.exit(2);
  }
  if (partial.pass !== false) {
    console.error("FAIL: toHaveTextContent('Error') passed on the text 'Error!' (partial match)");
    process.exit(1);
  }
  if (typeof m.toMatchTextContent !== "function") {
    console.error("ERROR: toMatchTextContent is not registered");
    process.exit(2);
  }
  const match = m.toMatchTextContent.call(ctx, element("Error!"), "Error");
  console.log("toMatchTextContent('Error') on 'Error!': pass=" + match.pass);
  if (match.pass !== true) {
    console.error("ERROR: toMatchTextContent did not match part of the text");
    process.exit(2);
  }
  console.log("PASS: toHaveTextContent matches the exact text; toMatchTextContent matches part of it");
})().catch((e) => {
  console.error("ERROR: " + (e && e.stack || e));
  process.exit(2);
});

